WITH OrgSpaceStats AS ( WITH inner_cte AS ( SELECT fo.ORGANIZATION_NAME, fo.DLC_KEY, COUNT(su.SPACE_UNIT_KEY) AS space_unit_count FROM FCLT_ORG_DLC_KEY fok JOIN FCLT_ORGANIZATION fo ON fok.DLC_KEY = fo.DLC_KEY JOIN SPACE_UNIT su ON fo.DLC_KEY = su.DLC_KEY GROUP BY fo.ORGANIZATION_NAME, fo.DLC_KEY ) SELECT ic.ORGANIZATION_NAME, ic.DLC_KEY, ic.space_unit_count, avg_stats.avg_space_units, CASE WHEN ic.space_unit_count > avg_stats.avg_space_units * 1.2 THEN 'LARGE_HOLDER' WHEN ic.space_unit_count < avg_stats.avg_space_units * 0.8 THEN 'SMALL_HOLDER' ELSE 'AVERAGE_HOLDER' END AS holder_category FROM inner_cte ic CROSS JOIN (SELECT AVG(space_unit_count) AS avg_space_units FROM inner_cte) avg_stats ), ProvostDeptStats AS ( WITH inner_cte AS ( SELECT m.DLC_NAME, f.FCLT_ORGANIZATION_KEY, f.DLC_KEY, COUNT(f.FCLT_ORGANIZATION_KEY) AS org_count, MIN(m.MASTER_DEPT_HIER_LEVEL_3_CODE) AS min_level3_code FROM MASTER_DEPT_HIERARCHY m JOIN FCLT_ORG_DLC_KEY f ON m.DLC_KEY = f.DLC_KEY WHERE m.MASTER_DEPT_HIER_LEVEL_2_NAME = 'Provost Area' GROUP BY m.DLC_NAME, f.FCLT_ORGANIZATION_KEY, f.DLC_KEY ) SELECT i.DLC_NAME, i.FCLT_ORGANIZATION_KEY, i.DLC_KEY, i.org_count, i.min_level3_code, MAX(m.MASTER_DEPT_HIER_LEVEL_3_CODE) AS max_level3_code FROM inner_cte i JOIN MASTER_DEPT_HIERARCHY m ON i.DLC_NAME = m.DLC_NAME GROUP BY i.DLC_NAME, i.FCLT_ORGANIZATION_KEY, i.DLC_KEY, i.org_count, i.min_level3_code ) SELECT pds.DLC_NAME, pds.FCLT_ORGANIZATION_KEY, pds.org_count, pds.min_level3_code, pds.max_level3_code, oss.ORGANIZATION_NAME, oss.space_unit_count, oss.avg_space_units, oss.holder_category FROM ProvostDeptStats pds JOIN OrgSpaceStats oss ON pds.DLC_KEY = oss.DLC_KEY ORDER BY pds.DLC_NAME, oss.ORGANIZATION_NAME;